<template>
  <section class="permissions" aria-labelledby="permissions-title">
    <header><p class="eyebrow">TEAM ACCESS</p><h2 id="permissions-title">Permissions</h2><p>Select a member, tick their access and save. Planned features stay disabled until implemented.</p></header>
    <div class="hierarchy" aria-label="Management hierarchy"><strong>Team Manager</strong><span aria-hidden="true">&darr;</span><strong>Head Coach</strong><span aria-hidden="true">&darr;</span><span>Coaches, analysts and team members</span></div>
    <p v-if="loading" role="status">Loading saved permissions...</p>
    <p v-else-if="!backendReady" class="availability" role="status">{{ unavailable || 'Configurable permissions require the backend update. Changes below are an unsaved draft and do not affect access.' }}</p>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <p v-if="notice" role="status">{{ notice }}</p>
    <label class="member-selector">Team member<select v-model="selectedId" :disabled="saving"><option value="" disabled>Select a member</option><option v-for="member in orderedMembers" :key="member.id" :value="member.id">{{ member.displayName }} - {{ roleName(member.role) }}</option></select></label>
    <template v-if="selected">
      <div class="member-heading"><div><h3>{{ selected.displayName }}</h3><p>{{ protectedRole ? 'Protected leadership permissions' : 'Individual team permissions' }}</p></div><span class="badge">{{ roleName(selected.role) }}</span></div>
      <p v-if="protectedRole" class="explanation">{{ selected.role === 'MANAGER' ? 'The Manager retains full team control and ownership transfer. The Head Coach cannot remove, replace or change the Manager.' : 'Head Coach manages team operations and staff permissions after backend activation. Only the Manager or global Admin can replace the Head Coach.' }}</p>
      <p v-else-if="!canConfigure" class="explanation">Only the Team Manager, Head Coach or global Admin can change team permissions.</p>
    </template>
    <div class="table-scroll"><table><caption>Feature permissions and development status</caption><thead><tr><th scope="col">Allow</th><th scope="col">Feature</th><th scope="col">Access provided</th><th scope="col">Availability</th></tr></thead><tbody><tr v-for="permission in options" :key="permission.key"><td><input type="checkbox" :aria-label="'Allow ' + permission.label" :checked="permission.status === 'CANDIDATE' && (protectedRole || draft.includes(permission.key))" :disabled="!selected || protectedRole || !canConfigure || saving || loading || permission.status !== 'CANDIDATE'" @change="toggle(permission.key, $event.target.checked)" /></td><th scope="row">{{ permission.label }}</th><td>{{ permission.description }}</td><td><span :class="['status',permission.status === 'PLANNED' ? 'planned' : 'ready']">{{ permission.status === 'PLANNED' ? 'Planned' : backendReady ? 'Available' : 'Backend update required' }}</span></td></tr></tbody></table></div>
    <div class="reserved"><h3>Protected actions</h3><p>Manage permissions: Manager and Head Coach only. Permission management cannot be delegated.</p><p>Transfer ownership: Manager only; global Admins can replace Managers.</p><p>Delete team: global Admin only. Private coach notes, branding and personal-pool AI sharing are not granted by these checkboxes.</p></div>
    <div v-if="selected && !protectedRole && canConfigure" class="actions"><button type="button" :disabled="saving || loading" @click="draft = []">Untick all</button><button type="button" :disabled="saving || loading || !dirty" @click="resetDraft">Discard changes</button><span role="status">{{ draft.length }} selected{{ dirty ? ' - Unsaved changes' : '' }}</span><button class="save" type="button" :disabled="!backendReady || !dirty || saving || loading" @click="save">{{ saving ? 'Saving...' : 'Save permissions' }}</button></div>
  </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import {getTeamPermissions,setMemberPermissions} from './teamHub.service.js';
import {featurePermissions,validPermissionList} from '../../../domains/team-hub/structure/feature-permissions.mjs';
const props=defineProps({teamId:{type:String,required:true},members:{type:Array,required:true},teamRole:{type:String,default:null},isPlatformAdmin:Boolean});
const selectedId=ref(''),draft=ref([]),snapshot=ref(null),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),unavailable=ref('');
let generation=0;
const rank=role=>({MANAGER:0,COACH:1,PLAYER:2}[role]??3);
const orderedMembers=computed(()=>props.members.filter(m=>m.status==='ACTIVE').slice().sort((a,b)=>rank(a.role)-rank(b.role)||(a.displayName||'').localeCompare(b.displayName||'')));
const selected=computed(()=>orderedMembers.value.find(m=>m.id===selectedId.value));
const protectedRole=computed(()=>['MANAGER','COACH'].includes(selected.value?.role));
const canConfigure=computed(()=>props.isPlatformAdmin||['MANAGER','COACH'].includes(props.teamRole));
const backendReady=computed(()=>snapshot.value?.permissionContract==='team-hub.permissions.v1');
const grant=computed(()=>snapshot.value?.members.find(m=>m.membershipId===selectedId.value));
const dirty=computed(()=>JSON.stringify([...draft.value].sort())!==JSON.stringify([...(grant.value?.permissions??[])].sort()));
const roleName=role=>({MANAGER:'Team Manager',COACH:'Head Coach',PLAYER:'Player'}[role]||'Team staff');
const options=featurePermissions;
function resetDraft(){draft.value=[...(grant.value?.permissions??[])];}
function toggle(key,checked){if(protectedRole.value||!canConfigure.value||!selected.value||saving.value)return;let next=draft.value.filter(p=>p!==key);if(checked)next.push(key);if(checked&&['reviews.read','reviews.write'].includes(key)&&!next.includes('pools.read'))next.push('pools.read');if(key==='reviews.write'&&checked&&!next.includes('reviews.read'))next.push('reviews.read');if(key==='pools.read'&&!checked)next=next.filter(p=>!['reviews.read','reviews.write'].includes(p));if(key==='reviews.read'&&!checked)next=next.filter(p=>p!=='reviews.write');draft.value=next;notice.value='';}
async function load(){const current=++generation;snapshot.value=null;draft.value=[];unavailable.value='';error.value='';if(!canConfigure.value){unavailable.value='Only team leadership can view and manage saved permissions.';loading.value=false;return;}loading.value=true;try{const result=await getTeamPermissions(props.teamId);if(current!==generation)return;if(result.permissionContract!=='team-hub.permissions.v1'||!Array.isArray(result.members)||result.members.some(m=>!validPermissionList(m.permissions)))throw Error('INVALID_PERMISSION_CONTRACT');snapshot.value=result;resetDraft();}catch{if(current===generation)unavailable.value='Saved permissions are unavailable. The backend update or an authorised connection is required. Checkbox changes remain an unsaved draft; access is unchanged.';}finally{if(current===generation)loading.value=false;}}
async function save(){if(!backendReady.value||!canConfigure.value||!selected.value||protectedRole.value||saving.value||!grant.value)return;if(!validPermissionList(draft.value)){error.value='Review the selected permissions.';return;}const current=generation,target=selectedId.value;saving.value=true;error.value='';notice.value='';try{const result=await setMemberPermissions({teamId:props.teamId,membershipId:target,permissions:[...draft.value].sort(),expectedTargetMembershipVersion:grant.value.version});if(current!==generation)return;if(result.grant?.membershipId!==target||!validPermissionList(result.grant.permissions))throw Error('INVALID_PERMISSION_CONTRACT');snapshot.value={...snapshot.value,team:result.team,members:snapshot.value.members.map(m=>m.membershipId===target?result.grant:m)};resetDraft();notice.value='Permissions saved and enforced by the team service.';}catch(reason){if(current===generation){await load();error.value=reason.message==='Team Hub changed; refresh and try again'?'The team changed. Saved permissions were reloaded; review and retry.':'Permissions could not be saved. No successful change was confirmed.';}}finally{saving.value=false;}}
watch(selectedId,()=>{resetDraft();notice.value='';error.value='';});
watch([()=>props.teamId,()=>props.members,()=>props.teamRole,()=>props.isPlatformAdmin],()=>{if(!orderedMembers.value.some(m=>m.id===selectedId.value))selectedId.value='';load();},{immediate:true});
</script>
<style scoped>
.permissions{color:#edf1f7}.eyebrow{font-size:10px;letter-spacing:.14em;color:#a1a9b7}h2{font-size:23px;margin:5px 0}header>p:last-child,.explanation{color:#a1a9b7;font-size:13px;line-height:1.6}.hierarchy{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:#14171d;border:1px solid #343b47;padding:20px;border-radius:10px;margin:22px 0}.hierarchy strong:first-child{color:#b6f36b}.availability,.error{background:#282218;border:1px solid #655338;padding:16px;border-radius:9px;color:#ecd2a7;font-size:13px;line-height:1.6}.error{border-color:#774047;color:#ffd1d3}.member-selector{display:grid;gap:8px;max-width:460px;font-size:13px;margin:24px 0}select{padding:12px;background:#14171d;border:1px solid #343b47;color:#edf1f7;border-radius:7px;font:inherit}.member-heading{display:flex;justify-content:space-between;align-items:center;gap:15px}.member-heading h3{margin:0;font-size:19px}.member-heading p{font-size:12px;color:#a1a9b7}.badge{padding:6px 10px;background:#263320;color:#b6f36b;border-radius:6px;font-size:12px}.table-scroll{overflow-x:auto;margin:24px 0;border:1px solid #343b47;border-radius:10px}table{border-collapse:collapse;width:100%;min-width:620px;background:#14171d;text-align:left;font-size:13px}caption{text-align:left;padding:18px;font-weight:600}th,td{padding:15px;border-top:1px solid #292e38}thead{background:#101319;color:#a1a9b7}td:nth-child(3){font-size:12px;color:#a1a9b7;line-height:1.5}input[type=checkbox]{width:18px;height:18px;accent-color:#b6f36b;cursor:pointer}input:disabled{cursor:not-allowed}.status{display:inline-block;font-size:11px;border-radius:5px;padding:5px 8px;background:#263320;color:#b6f36b}.planned{background:#252a33;color:#a1a9b7}.reserved{padding:18px;background:#14171d;border:1px solid #343b47;border-radius:10px}.reserved h3{margin:0;font-size:14px}.reserved p{font-size:12px;color:#a1a9b7;line-height:1.6}.actions{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:20px}.actions span{color:#a1a9b7;font-size:12px}button{padding:11px 14px;border-radius:7px;background:#202630;border:1px solid #404956;color:#edf1f7;font:inherit;font-size:12px;cursor:pointer}.save{background:#b6f36b;color:#19230f;border-color:#b6f36b}button:disabled{opacity:.5;cursor:not-allowed}:is(button,select,input):focus-visible{outline:2px solid #b6f36b;outline-offset:4px}@media(max-width:650px){.hierarchy{flex-direction:column;align-items:flex-start}.actions{align-items:stretch;flex-direction:column}}
</style>
